/* selectMasterMdCpSgMakerManagePopKepSgList */ SELECT X.BUYER ,X.AGENT ,X.SG_ID ,X.SG_NAME ,X.SG_ID ,X.APPROVAL_FLAG ,DECODE(X.APPROVAL_FLAG, 'Y', '품의완료', '품의대상') AS APPROVAL_TEXT ,X.TNT ,X.SIN_CON ,X.DEL_CON FROM ( SELECT S.BUYER AS BUYER ,S.AGENT AS AGENT ,S.SG_ID AS SG_ID ,MAX(SG.SG_NAME) AS SG_NAME ,MIN(S.APPROVAL_FLAG) AS APPROVAL_FLAG ,COUNT(*) AS TNT ,SUM(DECODE(S.STATUS, 'T', 1, 0)) AS SIN_CON ,SUM(DECODE(S.STATUS, 'D', 1, 0)) AS DEL_CON FROM DSS_S_BUYER_RESULT S, KEPSGMG SG WHERE S.BUYER = #{st_buyer_code} AND S.AGENT = #{st_agent_code} AND S.SG_ID = SG.SG_ID AND S.STATUS <> 'S' GROUP BY S.BUYER, S.AGENT, S.SG_ID ) X
WHERE X.APPROVAL_FLAG = #{st_sg_status}
ORDER BY 3

/* selectMasterMdCpSgMakerManagePopKepMgList */ SELECT X.BUYER ,X.AGENT ,X.SG_ID ,X.MAKER_CODE ,X.MAKER_NAME ,X.STATUS ,X.APPROVAL_FLAG AS APPROVAL_FLAG ,DECODE(X.APPROVAL_FLAG, 'Y', '품의완료', '품의대상') AS APPROVAL_TEXT ,X.USER_NAME ,X.CREATE_USER_ID ,X.CREATE_DATE FROM ( SELECT S.BUYER AS BUYER ,S.AGENT AS AGENT ,S.SG_ID AS SG_ID ,M.CODE AS MAKER_CODE ,M.TEXT1 AS MAKER_NAME ,S.STATUS AS STATUS ,S.APPROVAL_FLAG AS APPROVAL_FLAG ,(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = S.CREATE_USER_ID) AS USER_NAME ,S.CREATE_USER_ID ,TO_CHAR(CREATE_DATE, 'YYYY/MM/DD HH24:MI:SS') AS CREATE_DATE FROM DSS_S_BUYER_RESULT S, ICOMCOD1 M WHERE S.BUYER = #{st_buyer_code} AND S.AGENT = #{st_agent_code} AND S.MAKER_CODE = M.CODE AND M.TYPE = 'M104' AND M.FLAG = 'Y' AND S.STATUS <> 'S' AND S.SG_ID = #{st_sg_id} ) X
WHERE X.APPROVAL_FLAG = #{st_mk_status}
ORDER BY 8,9

